function countLetters(s) {
  const counts = new Array(26).fill(0);     // one counter per letter: index 0 is 'a', 25 is 'z'
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;        // 'a' is 97, so 'a' -> 0, 'b' -> 1, ...
  }
  return counts;
}

def count_letters(s):
    counts = [0] * 26                     # one counter per letter: index 0 is 'a', 25 is 'z'
    for ch in s:
        counts[ord(ch) - ord("a")] += 1   # ord gives the code: 'a' -> 0, 'b' -> 1, ...
    return counts

int[] countLetters(String s) {
    int[] counts = new int[26];                  // one counter per letter: index 0 is 'a', 25 is 'z'
    for (int i = 0; i < s.length(); i++) {
        counts[s.charAt(i) - 'a']++;             // a char is a number, so 'c' - 'a' is 2
    }
    return counts;
}

vector<int> countLetters(const string& s) {
    vector<int> counts(26, 0);                   // one counter per letter: index 0 is 'a', 25 is 'z'
    for (char ch : s) {
        counts[ch - 'a']++;                      // a char is a number, so 'c' - 'a' is 2
    }
    return counts;
}
